  FROM (VALUES
    ('2dc2b921-9320-57c9-9896-38ac6795ee89'::uuid, '98996db6-7f9f-5276-81b2-c569c6c867f6'::uuid, 'D’où vient le nom de la poésie lyrique ?', 'mcq', '["De la lyre, l’instrument des poètes grecs","Du grec « lyros », qui signifie amour","Du nom du poète Lyrios","Du mot « lire »"]'::jsonb, 0, 'À l’origine, cette poésie se chantait.', 1),
    ('acbdc652-1110-517c-a3cb-4925361b5a7d'::uuid, '98996db6-7f9f-5276-81b2-c569c6c867f6'::uuid, 'Qu’exprime la poésie lyrique ?', 'mcq', '["Les sentiments personnels du poète","Les exploits des héros","Les règles de la société","Des récits historiques"]'::jsonb, 0, 'Le « je » y est omniprésent.', 2),
    ('27ede890-115a-5fab-9b32-6c1869ed52c8'::uuid, '98996db6-7f9f-5276-81b2-c569c6c867f6'::uuid, 'Quelle poétesse grecque du VIe siècle avant J.-C. chante le trouble amoureux ?', 'mcq', '["Sappho","Antigone","Louise Labé","Marie de France"]'::jsonb, 0, 'Elle vivait sur l’île de Lesbos.', 3),
    ('a4b3e4dd-160f-5652-931e-204303390472'::uuid, '98996db6-7f9f-5276-81b2-c569c6c867f6'::uuid, 'Qu’est-ce que l’amour courtois ?', 'mcq', '["Le service d’une dame inaccessible par le poète","Un mariage arrangé à la cour","Un amour partagé et heureux","Une déclaration faite devant le roi"]'::jsonb, 0, 'Les troubadours l’inventent au Moyen Âge.', 4),
    ('e78251c6-3260-5969-9e93-168e185a18d8'::uuid, '98996db6-7f9f-5276-81b2-c569c6c867f6'::uuid, 'Quel poète du XVIe siècle a écrit « Mignonne, allons voir si la rose… » ?', 'mcq', '["Ronsard","Hugo","Musset","Apollinaire"]'::jsonb, 0, 'Il appartient à la Pléiade.', 5),
    ('0cca8cf1-5a6d-5167-b682-669e6f585d37'::uuid, '98996db6-7f9f-5276-81b2-c569c6c867f6'::uuid, 'Combien de vers compte un sonnet ?', 'mcq', '["14","12","10","16"]'::jsonb, 0, 'Deux quatrains suivis de deux tercets.', 6),
    ('b01a642f-4fe2-57e7-be72-2d78c77e6a75'::uuid, '98996db6-7f9f-5276-81b2-c569c6c867f6'::uuid, 'Quelle figure de style consiste à s’adresser directement à un être ou à une chose ?', 'mcq', '["L’apostrophe","La métaphore","L’antithèse","L’allitération"]'::jsonb, 0, '« Ô temps, suspends ton vol ! »', 7),
    ('5cbd5a10-560d-5207-b6a2-5f052ed437dd'::uuid, '98996db6-7f9f-5276-81b2-c569c6c867f6'::uuid, 'La poésie lyrique est un genre né au XIXe siècle.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle remonte à l’Antiquité grecque, avec Sappho.', 8),
    ('821f9ac8-ba49-5c2e-81a4-5a315bf62a40'::uuid, 'e132fcb4-ff31-5aec-a94f-e66f59bf8aa1'::uuid, 'Dans quel recueil « Demain, dès l’aube… » a-t-il été publié ?', 'mcq', '["Les Contemplations","Les Misérables","Les Fleurs du mal","Les Rayons et les Ombres"]'::jsonb, 0, 'Publié en 1856.', 1),
    ('28801e78-87f7-5acd-9ff4-dcda9b2ef952'::uuid, 'e132fcb4-ff31-5aec-a94f-e66f59bf8aa1'::uuid, 'À qui ce poème est-il adressé ?', 'mcq', '["À Léopoldine, la fille du poète, morte noyée","À une femme aimée","À la France","À un ami disparu"]'::jsonb, 0, 'Elle s’est noyée à 19 ans à Villequier, en 1843.', 2),
    ('58302433-6cf4-5fe5-9395-2bfe3c2da938'::uuid, 'e132fcb4-ff31-5aec-a94f-e66f59bf8aa1'::uuid, 'Quelle est la forme du poème ?', 'mcq', '["Trois quatrains d’alexandrins en rimes croisées","Un sonnet","Un poème en prose","Quatre tercets en vers libres"]'::jsonb, 0, 'Une forme simple, presque nue.', 3),
    ('26f688c0-ee1d-55d0-b491-40f988d79597'::uuid, 'e132fcb4-ff31-5aec-a94f-e66f59bf8aa1'::uuid, 'Quel mot du dernier vers renverse le sens du poème ?', 'mcq', '["« tombe »","« bouquet »","« bruyère »","« aube »"]'::jsonb, 0, 'Le lecteur croyait lire un poème d’amour.', 4),
    ('6fef855d-ba40-5226-8178-4ad30f2abccc'::uuid, 'e132fcb4-ff31-5aec-a94f-e66f59bf8aa1'::uuid, 'Quel temps domine dans le poème ?', 'mcq', '["Le futur","Le passé simple","L’imparfait","Le présent"]'::jsonb, 0, 'Il rend le voyage inéluctable.', 5),
    ('d1af8090-f23a-5fc2-9d74-bceadc494a7f'::uuid, 'e132fcb4-ff31-5aec-a94f-e66f59bf8aa1'::uuid, 'Que refuse de regarder le poète pendant son voyage ?', 'mcq', '["L’or du soir et les voiles descendant vers Harfleur","La foule sur les routes","La mer et le ciel","Les maisons du village"]'::jsonb, 0, 'Les négations montrent qu’il s’est fermé au monde.', 6),
    ('d5129f56-fedf-5ad7-9f21-ba42e372fdb3'::uuid, 'e132fcb4-ff31-5aec-a94f-e66f59bf8aa1'::uuid, 'Que dépose le poète sur la tombe ?', 'mcq', '["Un bouquet de houx vert et de bruyère en fleur","Une rose blanche","Une couronne de lauriers","Une lettre"]'::jsonb, 0, 'Le houx persistant et la bruyère fragile : fidélité et deuil.', 7),
    ('9e723703-4137-5ee1-b83c-3f1574842b96'::uuid, 'e132fcb4-ff31-5aec-a94f-e66f59bf8aa1'::uuid, 'Le poème nomme explicitement la mort de Léopoldine.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il ne dit ni « fille » ni « mort » : c’est cette retenue qui fait sa force.', 8),
    ('0e474cfa-2629-55a9-b4b4-13db3b24c5c6'::uuid, '11f8df83-c23c-5927-8ff7-42af4811bfe8'::uuid, 'En quoi consiste la règle des trois unités ?', 'mcq', '["Une seule action, un seul lieu, une seule journée","Trois actes, trois personnages, trois lieux","Trois unités de temps de trois heures","Une unité de ton, de style et de genre"]'::jsonb, 0, 'C’est la règle centrale du théâtre classique.', 1),
    ('b8305577-1d96-5bcc-9da9-5a14cc57f66e'::uuid, '11f8df83-c23c-5927-8ff7-42af4811bfe8'::uuid, 'Que signifie la règle de bienséance ?', 'mcq', '["Ni sang ni violence ne doivent être montrés sur scène","Les personnages doivent être polis","La pièce doit bien finir","Le public doit rester silencieux"]'::jsonb, 0, 'Les morts sont racontées, jamais représentées.', 2),
    ('d785c4bd-536a-525f-83fd-54e3590ce6a1'::uuid, '11f8df83-c23c-5927-8ff7-42af4811bfe8'::uuid, 'Qu’est-ce que la catharsis ?', 'mcq', '["La purgation des passions du spectateur par la terreur et la pitié","Le dénouement heureux d’une pièce","Le monologue final du héros","La règle de l’unité de lieu"]'::jsonb, 0, 'La notion vient d’Aristote.', 3),
    ('d68f9aae-3371-58c2-b608-c12ba9232f7a'::uuid, '11f8df83-c23c-5927-8ff7-42af4811bfe8'::uuid, 'Pourquoi Titus renonce-t-il à Bérénice ?', 'mcq', '["Parce que Rome interdit à son empereur d’épouser une reine étrangère","Parce qu’il ne l’aime plus","Parce qu’elle en aime un autre","Parce qu’elle est morte"]'::jsonb, 0, 'C’est le conflit entre l’amour et le devoir.', 4),
    ('27ff3375-8eec-5206-9d75-92addd34a9ff'::uuid, '11f8df83-c23c-5927-8ff7-42af4811bfe8'::uuid, 'Qui est Antiochus dans la pièce ?', 'mcq', '["Le roi de Comagène, ami de Titus, qui aime Bérénice en secret","Le père de Bérénice","Un sénateur romain","Le rival militaire de Titus"]'::jsonb, 0, 'Il forme le troisième sommet du triangle.', 5),
    ('643fa758-6990-5f55-8203-4e49469d6c87'::uuid, '11f8df83-c23c-5927-8ff7-42af4811bfe8'::uuid, 'Comment s’achève Bérénice ?', 'mcq', '["Par un triple renoncement, sans aucune mort","Par le suicide de Bérénice","Par le mariage des deux amants","Par la mort de Titus"]'::jsonb, 0, 'Racine prouve qu’une tragédie n’exige ni sang ni morts.', 6),
    ('f64002f8-143d-502d-8b77-4f0e483825b6'::uuid, '11f8df83-c23c-5927-8ff7-42af4811bfe8'::uuid, 'Quel vers l’alexandrin compte-t-il ?', 'mcq', '["Douze syllabes","Dix syllabes","Huit syllabes","Quatorze syllabes"]'::jsonb, 0, 'La tragédie classique s’écrit en alexandrins à rimes plates.', 7),
    ('e7f1ea5f-3d11-5d0e-b7ef-b93e44be32f9'::uuid, '11f8df83-c23c-5927-8ff7-42af4811bfe8'::uuid, 'Le héros tragique dispose toujours d’une issue favorable.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est justement l’absence d’issue qui définit le tragique.', 8),
    ('747bd55e-f712-5b8d-826e-be92258be56f'::uuid, '22fde46a-211e-538e-8ad8-f0c896b1d915'::uuid, 'Quel dramaturge du XVIIe siècle la comédie du XVIIIe prend-elle pour modèle ?', 'mcq', '["Molière","Racine","Corneille","Voltaire"]'::jsonb, 0, 'Types et procédés comiques lui sont hérités.', 1),
    ('0adee0eb-b852-5dde-a8b8-fffeb9933377'::uuid, '22fde46a-211e-538e-8ad8-f0c896b1d915'::uuid, 'Qu’est-ce qu’un quiproquo ?', 'mcq', '["Un malentendu où l’on prend une chose ou une personne pour une autre","Un jeu de mots","Une chute sur scène","Un monologue adressé au public"]'::jsonb, 0, 'C’est un comique de situation.', 2),
    ('476e7dae-48a0-5a17-8fbc-6700ebf0e6cf'::uuid, '22fde46a-211e-538e-8ad8-f0c896b1d915'::uuid, 'Comment évolue le rôle du valet au XVIIIe siècle ?', 'mcq', '["Il devient l’égal intellectuel de son maître, souvent plus lucide","Il disparaît de la scène","Il devient muet","Il ne fait plus rire du tout"]'::jsonb, 0, 'Figaro en est l’aboutissement.', 3),
    ('a991ff7f-8ce3-5b23-8348-7fc8345461ad'::uuid, '22fde46a-211e-538e-8ad8-f0c896b1d915'::uuid, 'Qu’appelle-t-on le marivaudage ?', 'mcq', '["Un dialogue léger et spirituel où les personnages avancent masqués","Une farce grossière","Un long monologue tragique","Une critique politique directe"]'::jsonb, 0, 'Le spectateur comprend avant les personnages.', 4),
    ('eeaf8eff-ba1d-58b5-8181-f8f871c1eb76'::uuid, '22fde46a-211e-538e-8ad8-f0c896b1d915'::uuid, 'Quel est l’obstacle principal à l’amour chez Marivaux ?', 'mcq', '["L’amour-propre des personnages","L’opposition du père","La différence de religion","La guerre"]'::jsonb, 0, 'Ils refusent de reconnaître leur sentiment.', 5),
    ('db0fb488-1fde-50bb-b950-f3ceefd6d4e7'::uuid, '22fde46a-211e-538e-8ad8-f0c896b1d915'::uuid, 'Quelle pièce de Beaumarchais fut d’abord interdite par Louis XVI ?', 'mcq', '["Le Mariage de Figaro","Le Jeu de l’amour et du hasard","Bérénice","L’Assommoir"]'::jsonb, 0, 'Sa critique sociale était jugée trop hardie.', 6),
    ('f4ba9ecd-32c7-55c8-ba6f-8621888d36ab'::uuid, '22fde46a-211e-538e-8ad8-f0c896b1d915'::uuid, 'Qu’est-ce que la comédie sensible ?', 'mcq', '["Une comédie qui mêle le rire et l’émotion","Une comédie sans dialogue","Une comédie en un seul acte","Une comédie jouée sans décor"]'::jsonb, 0, 'Elle prépare le drame du siècle suivant.', 7),
    ('c71485e3-8453-57fe-b451-8f26ec1a2f7e'::uuid, '22fde46a-211e-538e-8ad8-f0c896b1d915'::uuid, 'La comédie du XVIIIe siècle se contente de faire rire, sans critiquer la société.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Sous l’influence des Lumières, la critique sociale y devient centrale.', 8),
    ('f665f6d2-2497-5433-9e3a-330f5dbf17d5'::uuid, '11f10d9c-242a-5e5f-98fb-6133c5923478'::uuid, 'En quelle année Le Jeu de l’amour et du hasard a-t-il été créé ?', 'mcq', '["1730","1670","1784","1856"]'::jsonb, 0, 'C’est une comédie en trois actes et en prose.', 1),
    ('a0420c1f-99aa-552a-9d22-e9597440484e'::uuid, '11f10d9c-242a-5e5f-98fb-6133c5923478'::uuid, 'Pourquoi Silvia échange-t-elle son rôle avec sa servante ?', 'mcq', '["Pour observer son futur époux sans être reconnue","Pour fuir le mariage","Pour punir Lisette","Pour obéir à son père"]'::jsonb, 0, 'Dorante a eu exactement la même idée.', 2),
    ('b65e6d6e-be93-5ddb-85c8-85ed16d0d246'::uuid, '11f10d9c-242a-5e5f-98fb-6133c5923478'::uuid, 'Comment s’appelle le valet de Dorante ?', 'mcq', '["Arlequin","Mario","Orgon","Figaro"]'::jsonb, 0, 'Il joue le rôle du maître pendant que Dorante joue le valet.', 3),
    ('8f7a5f6f-df8d-5b31-9528-4fc3e049ffa6'::uuid, '11f10d9c-242a-5e5f-98fb-6133c5923478'::uuid, 'Qu’est-ce que le double registre dans cette pièce ?', 'mcq', '["Le public sait ce que les personnages ignorent","Les personnages parlent deux langues","La pièce mêle vers et prose","Deux intrigues se déroulent en parallèle"]'::jsonb, 0, 'C’est le ressort comique principal.', 4),
    ('51d3a42c-0e30-57f5-a8a9-1b83ace0920f'::uuid, '11f10d9c-242a-5e5f-98fb-6133c5923478'::uuid, 'Quel est le véritable sujet de la pièce ?', 'mcq', '["L’épreuve du sentiment face au préjugé social","La lutte pour le pouvoir","La critique de la religion","La guerre entre deux familles"]'::jsonb, 0, 'Chacun doit choisir entre son cœur et son rang.', 5),
    ('1f774d6b-461c-579e-9f83-eb152bfb2f2d'::uuid, '11f10d9c-242a-5e5f-98fb-6133c5923478'::uuid, 'Qui révèle son identité le premier ?', 'mcq', '["Dorante","Silvia","Arlequin","Lisette"]'::jsonb, 0, 'Silvia prolonge l’épreuve pour être aimée pour elle-même.', 6),
    ('188e7b2e-a1b4-5cc4-bf93-a35a862b9875'::uuid, '11f10d9c-242a-5e5f-98fb-6133c5923478'::uuid, 'Qu’est-ce qu’un aparté ?', 'mcq', '["Une réplique adressée au public que les autres personnages n’entendent pas","Un monologue en fin d’acte","Un dialogue en coulisses","Une didascalie"]'::jsonb, 0, 'Marivaux en use abondamment.', 7),
    ('39b16741-88f3-5a5c-87b5-ae1ad740a7e6'::uuid, '11f10d9c-242a-5e5f-98fb-6133c5923478'::uuid, 'À la fin de la pièce, l’ordre social est renversé.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Maîtres et valets se marient chacun dans leur condition.', 8),
    ('a43d25f9-3569-5764-9c9e-f2ec1c0bdfc8'::uuid, '84102ba6-6d18-55b4-9ccd-5664830b1a52'::uuid, 'Dans quel texte Victor Hugo théorise-t-il le drame romantique ?', 'mcq', '["La Préface de Cromwell","Les Contemplations","La Préface de Bérénice","L’Art poétique"]'::jsonb, 0, 'Publiée en 1827.', 1),
    ('df621411-e182-538d-929d-523e739cc0c3'::uuid, '84102ba6-6d18-55b4-9ccd-5664830b1a52'::uuid, 'Quelle règle classique le drame romantique rejette-t-il ?', 'mcq', '["La règle des trois unités","L’usage de la prose","La présence d’un héros","La division en actes"]'::jsonb, 0, 'Il multiplie lieux, époques et intrigues.', 2),
    ('bb83920e-8e1c-5c5f-a060-213d22b9374f'::uuid, '84102ba6-6d18-55b4-9ccd-5664830b1a52'::uuid, 'Que mélange le drame romantique ?', 'mcq', '["Le sublime et le grotesque, le comique et le tragique","Le théâtre et le roman","La poésie et la musique","Le français et le latin"]'::jsonb, 0, 'Hugo en fait le principe même du genre.', 3),
    ('53a8662b-8ef4-59cf-b3bb-8d719ce250d5'::uuid, '84102ba6-6d18-55b4-9ccd-5664830b1a52'::uuid, 'En quelle année Lorenzaccio a-t-il été écrit ?', 'mcq', '["1834","1827","1896","1730"]'::jsonb, 0, 'Jugée injouable, la pièce ne sera créée qu’en 1896.', 4),
    ('5852afab-fdb8-5827-aef7-c3b5517d997d'::uuid, '84102ba6-6d18-55b4-9ccd-5664830b1a52'::uuid, 'Qui Lorenzo assassine-t-il ?', 'mcq', '["Alexandre de Médicis, le tyran de Florence","Côme de Médicis","Son propre père","Le duc de Milan"]'::jsonb, 0, 'Il prépare ce meurtre depuis des années.', 5),
    ('80e8804a-613d-5ded-8695-e948129ec96e'::uuid, '84102ba6-6d18-55b4-9ccd-5664830b1a52'::uuid, 'Que se passe-t-il après le meurtre ?', 'mcq', '["Rien ne change : un autre Médicis est élu","Florence devient une république","Lorenzo prend le pouvoir","Le peuple se soulève"]'::jsonb, 0, 'C’est l’échec total de l’engagement.', 6),
    ('28ce7fd7-4a62-5ac2-a4f4-476c2d1e26e2'::uuid, '84102ba6-6d18-55b4-9ccd-5664830b1a52'::uuid, 'Que signifie la réplique « Le vice a été pour moi un vêtement ; maintenant il est collé à ma peau » ?', 'mcq', '["À force de jouer le débauché, Lorenzo l’est devenu","Lorenzo regrette sa richesse","Lorenzo se déguise pour fuir","Lorenzo accuse le tyran"]'::jsonb, 0, 'Le masque a dévoré le visage.', 7),
    ('11035b7f-bb4e-50db-bd90-5de9c6fec135'::uuid, '84102ba6-6d18-55b4-9ccd-5664830b1a52'::uuid, 'Lorenzaccio a été jouée dès sa publication.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Jugée injouable, elle attend 1896 et Sarah Bernhardt.', 8),
    ('ef122a82-af65-5174-beb3-65d58e63144b'::uuid, '8d20e311-8a15-5fee-9755-aed5143fb367'::uuid, 'Pourquoi Le Cid est-il d’abord appelé tragi-comédie ?', 'mcq', '["Il a la gravité d’une tragédie mais une fin heureuse","Il alterne scènes comiques et tragiques","Il est joué par des comédiens amateurs","Il mêle vers et prose"]'::jsonb, 0, 'Corneille le rebaptisera « tragédie » en 1648.', 1),
    ('56dc5b4b-70a1-529d-a686-5abd6db0ca79'::uuid, '8d20e311-8a15-5fee-9755-aed5143fb367'::uuid, 'Pourquoi Rodrigue doit-il tuer le père de Chimène ?', 'mcq', '["Parce que celui-ci a giflé son propre père, trop vieux pour se venger","Parce qu’il convoite sa fortune","Parce que le roi le lui ordonne","Parce qu’il l’a trahi à la guerre"]'::jsonb, 0, 'L’honneur familial exige réparation.', 2),
    ('6087d75a-cba9-548f-8cb8-13afdf423466'::uuid, '8d20e311-8a15-5fee-9755-aed5143fb367'::uuid, 'Qu’est-ce qu’un dilemme cornélien ?', 'mcq', '["Un choix entre deux valeurs également hautes, impossibles à concilier","Un choix entre le bien et le mal","Une hésitation entre deux amours","Un pari sur l’avenir"]'::jsonb, 0, 'Quel que soit le choix, le héros perd quelque chose d’essentiel.', 3),
    ('eb804fbb-6101-5324-bd89-07856a486451'::uuid, '8d20e311-8a15-5fee-9755-aed5143fb367'::uuid, 'Comment appelle-t-on le monologue de Rodrigue à l’acte I ?', 'mcq', '["Les stances","L’aparté","La tirade des Maures","Le prologue"]'::jsonb, 0, '« Percé jusques au fond du cœur… »', 4),
    ('9212d09e-d2e6-5998-86ca-15dacd1d276d'::uuid, '8d20e311-8a15-5fee-9755-aed5143fb367'::uuid, 'Pourquoi Rodrigue est-il surnommé « le Cid » ?', 'mcq', '["Parce qu’il a vaincu les Maures, qui le nomment « le seigneur »","Parce que c’est son nom de naissance","Parce que le roi le lui a donné à sa naissance","Parce qu’il est le fils de Don Diègue"]'::jsonb, 0, 'Le mot vient de l’arabe et signifie « seigneur ».', 5),
    ('d85167db-c2ab-5f14-b935-15dcdc69cf5f'::uuid, '8d20e311-8a15-5fee-9755-aed5143fb367'::uuid, 'Qu’est-ce qui définit le héros cornélien ?', 'mcq', '["Sa volonté : il choisit et grandit par son choix","Sa passion, qu’il subit","Sa naissance illustre","Sa ruse"]'::jsonb, 0, 'C’est ce qui le distingue du héros racinien.', 6),
    ('c3638ef2-697c-5c0a-b707-fa304dfe9146'::uuid, '8d20e311-8a15-5fee-9755-aed5143fb367'::uuid, 'Qu’est-ce que la querelle du Cid ?', 'mcq', '["La polémique sur le respect des unités et de la bienséance dans la pièce","Un duel entre Corneille et Racine","Un procès intenté à Corneille","Une dispute entre deux troupes de théâtre"]'::jsonb, 0, 'Elle contribua à fixer les règles du théâtre classique.', 7),
    ('617cee0c-c098-508a-a5f4-0ffe3b8f71e3'::uuid, '8d20e311-8a15-5fee-9755-aed5143fb367'::uuid, 'Le Cid se termine par la mort des deux amants.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le roi accorde un délai d’un an : la fin reste ouverte et heureuse.', 8),
    ('e7e8618e-9610-5f42-b44c-73924f06c8c4'::uuid, 'b084a9ab-63b9-558e-abb2-a1175533a742'::uuid, 'Qu’est-ce qui distingue une nouvelle d’un roman ?', 'mcq', '["Sa brièveté, son intrigue resserrée et sa chute","Sa forme versifiée","Son sujet toujours historique","Son absence de personnages"]'::jsonb, 0, 'Le roman prend son temps, la nouvelle vise.', 1),
    ('0a3b2684-8f7a-5daa-98a8-19d30efd1ac9'::uuid, 'b084a9ab-63b9-558e-abb2-a1175533a742'::uuid, 'Qu’est-ce que la chute d’une nouvelle ?', 'mcq', '["Une fin brève et frappante, qui retourne souvent le sens du récit","Le moment le plus dramatique du milieu","La description du décor","Le premier paragraphe"]'::jsonb, 0, 'Elle est toujours préparée par des indices.', 2),
    ('1c6dd4a8-527c-59b6-a117-7e096b3d25d4'::uuid, 'b084a9ab-63b9-558e-abb2-a1175533a742'::uuid, 'Quel auteur du XVIIIe siècle a fait du récit bref un outil philosophique ?', 'mcq', '["Voltaire","Maupassant","Poe","Zola"]'::jsonb, 0, 'Candide et Micromégas sont des contes philosophiques.', 3),
    ('8a536afc-4c43-56d4-a2a7-bdf1046bba29'::uuid, 'b084a9ab-63b9-558e-abb2-a1175533a742'::uuid, 'Quel siècle est l’âge d’or de la nouvelle en France ?', 'mcq', '["Le XIXe siècle","Le XVIIe siècle","Le XVIIIe siècle","Le XXe siècle"]'::jsonb, 0, 'La presse en publiait chaque semaine.', 4),
    ('754db117-c008-52f8-bf43-a22f85d2880d'::uuid, 'b084a9ab-63b9-558e-abb2-a1175533a742'::uuid, 'Quelle nouvelle fantastique Maupassant a-t-il écrite ?', 'mcq', '["Le Horla","La Parure","Boule de Suif","La Vénus d’Ille"]'::jsonb, 0, 'La Vénus d’Ille est de Mérimée.', 5),
    ('52f751a8-1604-530f-8bae-4e0d1eb7987c'::uuid, 'b084a9ab-63b9-558e-abb2-a1175533a742'::uuid, 'Que caractérise le registre fantastique ?', 'mcq', '["L’irruption de l’inexplicable dans un cadre réaliste","L’acceptation du surnaturel comme allant de soi","La peinture fidèle du réel","L’enquête policière"]'::jsonb, 0, 'Dans le merveilleux, au contraire, le surnaturel ne surprend personne.', 6),
    ('18688357-0079-5a7d-af59-5197a4a2c4c4'::uuid, 'b084a9ab-63b9-558e-abb2-a1175533a742'::uuid, 'Quel écrivain russe est un maître de la nouvelle ?', 'mcq', '["Tchekhov","Balzac","Bradbury","Buzzati"]'::jsonb, 0, 'Ses nouvelles peignent le quotidien avec une précision aiguë.', 7),
    ('9672795b-4aae-52e2-bc54-5cf09bf44ce8'::uuid, 'b084a9ab-63b9-558e-abb2-a1175533a742'::uuid, 'Une nouvelle peut comporter autant de personnages qu’un roman.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Sa brièveté impose peu de personnages, décrits en quelques traits.', 8),
    ('bde8f657-2436-5268-8d8c-341bdbcb1ee4'::uuid, 'da940e87-9dc8-5289-ae73-8a9345f169b7'::uuid, 'Qui a fondé le naturalisme ?', 'mcq', '["Émile Zola","Gustave Flaubert","Honoré de Balzac","Guy de Maupassant"]'::jsonb, 0, 'Il l’expose dans Le Roman expérimental.', 1),
    ('83bea1b1-4355-526e-90b0-b81362ef6268'::uuid, 'da940e87-9dc8-5289-ae73-8a9345f169b7'::uuid, 'Qu’est-ce qui distingue le naturalisme du réalisme ?', 'mcq', '["Il applique au roman la méthode scientifique, étudiant l’hérédité et le milieu","Il idéalise la réalité","Il refuse toute documentation","Il ne peint que la bourgeoisie"]'::jsonb, 0, 'Le romancier y est « observateur et expérimentateur ».', 2),
    ('bc3aabed-55ff-511c-b87e-32a22bc2d682'::uuid, 'da940e87-9dc8-5289-ae73-8a9345f169b7'::uuid, 'Comment s’appelle le cycle romanesque de Zola ?', 'mcq', '["Les Rougon-Macquart","La Comédie humaine","Les Misérables","Les Contemplations"]'::jsonb, 0, 'Vingt romans sur cinq générations d’une même famille.', 3),
    ('d58ce8c4-9131-5ce6-8819-53ea9ae3a8c9'::uuid, 'da940e87-9dc8-5289-ae73-8a9345f169b7'::uuid, 'Quel est le sujet de L’Assommoir ?', 'mcq', '["La vie et la déchéance d’une blanchisseuse dans le monde ouvrier","La montée d’un banquier","La guerre de 1870","La vie d’une comédienne"]'::jsonb, 0, 'C’est le premier grand roman français sur le monde ouvrier.', 4),
    ('fbc34b53-a734-5ded-ab9a-0b9222c53c18'::uuid, 'da940e87-9dc8-5289-ae73-8a9345f169b7'::uuid, 'Que désigne le mot « assommoir » ?', 'mcq', '["Un débit d’alcool populaire","Un atelier de blanchisserie","Un immeuble ouvrier","Un outil de zingueur"]'::jsonb, 0, 'La boutique du père Colombe, où travaille l’alambic.', 5),
    ('59f2a20b-e932-5206-b35e-bca395508e54'::uuid, 'da940e87-9dc8-5289-ae73-8a9345f169b7'::uuid, 'Comment s’appelle l’héroïne de L’Assommoir ?', 'mcq', '["Gervaise Macquart","Nana","Emma Bovary","Chimène"]'::jsonb, 0, 'Sa fille Nana sera l’héroïne d’un autre roman du cycle.', 6),
    ('43a85802-35dd-562c-bf3f-28545b0e2ec5'::uuid, 'da940e87-9dc8-5289-ae73-8a9345f169b7'::uuid, 'Qu’est-ce qui a fait scandale dans L’Assommoir ?', 'mcq', '["L’entrée de la langue populaire, argot compris, jusque dans la narration","La présence de personnages historiques","Sa longueur excessive","Son absence de dialogue"]'::jsonb, 0, 'Le roman fut accusé de complaisance dans la misère.', 7),
    ('113499ee-206f-554a-9e8a-0e94788651f2'::uuid, 'da940e87-9dc8-5289-ae73-8a9345f169b7'::uuid, 'Zola condamne moralement son héroïne.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il montre comment le milieu défait une femme courageuse.', 8),
    ('64759814-00d1-5389-b1c5-e5e74ff58125'::uuid, '7af5bf8d-528f-566a-a974-ef15f6f73e73'::uuid, 'Quel bijou Mathilde emprunte-t-elle ?', 'mcq', '["Une rivière de diamants","Un collier de perles","Une bague en or","Une broche de saphirs"]'::jsonb, 0, 'Elle appartient à son amie Madame Forestier.', 1),
    ('893d1881-328d-523b-91e5-5cdd67664a89'::uuid, '7af5bf8d-528f-566a-a974-ef15f6f73e73'::uuid, 'Combien de temps le couple Loisel met-il à rembourser la parure ?', 'mcq', '["Dix ans","Un an","Trois ans","Vingt ans"]'::jsonb, 0, 'Ces dix années sont condensées en une ellipse.', 2),
    ('59f4a746-5ebb-5cc0-8150-50746392a9ba'::uuid, '7af5bf8d-528f-566a-a974-ef15f6f73e73'::uuid, 'Quelle est la chute de la nouvelle ?', 'mcq', '["La parure empruntée était fausse","Mathilde retrouve le bijou perdu","Madame Forestier était ruinée","Le mari de Mathilde avait volé le bijou"]'::jsonb, 0, 'Elle valait au plus cinq cents francs.', 3),
    ('a7adc5a4-56a5-5ec2-9eef-2cc5a8f37b1f'::uuid, '7af5bf8d-528f-566a-a974-ef15f6f73e73'::uuid, 'Qu’est-ce qu’une ellipse dans un récit ?', 'mcq', '["Le passage sous silence d’une période de temps","Une description très détaillée","Un dialogue rapporté","Un retour en arrière"]'::jsonb, 0, 'Les dix années de remboursement tiennent en un paragraphe.', 4),
    ('9c50d750-cc4c-533d-b3b9-f4f3a6c3887a'::uuid, '7af5bf8d-528f-566a-a974-ef15f6f73e73'::uuid, 'Quel type de narrateur Maupassant emploie-t-il ?', 'mcq', '["Un narrateur externe, à la troisième personne","Un narrateur personnage","Un narrateur à la deuxième personne","Plusieurs narrateurs successifs"]'::jsonb, 0, 'Il rapporte sans commenter.', 5),
    ('5c4f0582-fe67-54dd-aed0-7416b98f10ea'::uuid, '7af5bf8d-528f-566a-a974-ef15f6f73e73'::uuid, 'Que dénonce la nouvelle ?', 'mcq', '["Le poids des apparences dans la société","La corruption des ministères","La guerre franco-prussienne","L’exploitation des ouvriers"]'::jsonb, 0, 'Une faute minuscule y entraîne une punition démesurée.', 6),
    ('8396ae0b-caba-5406-afe2-826f64fe1f25'::uuid, '7af5bf8d-528f-566a-a974-ef15f6f73e73'::uuid, 'Qui a réalisé l’adaptation télévisée de « La Parure » en 2007 ?', 'mcq', '["Claude Chabrol","François Truffaut","Jean Renoir","Louis Malle"]'::jsonb, 0, 'Dans la collection Chez Maupassant.', 7),
    ('fd6b8ed5-6bc4-5650-b786-3fedf30dd238'::uuid, '7af5bf8d-528f-566a-a974-ef15f6f73e73'::uuid, 'La chute de « La Parure » arrive sans aucun indice préalable.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La boîte qui n’est pas d’origine et le bijoutier qui ne reconnaît pas la parure l’annonçaient.', 8),
    ('7d1bd550-13ec-53fd-a72f-e61d63c45bd6'::uuid, 'efc6493b-a5c3-5b71-ac25-181b5fb94074'::uuid, 'Qu’est-ce qui caractérise le récit fantastique ?', 'mcq', '["L’hésitation entre une explication rationnelle et le surnaturel","L’acceptation du surnaturel comme allant de soi","L’explication scientifique de l’étrange","L’absence de tout événement étrange"]'::jsonb, 0, 'C’est ce qui le distingue du merveilleux et de la science-fiction.', 1),
    ('53fab131-4159-5d12-8e6f-82958db6afd8'::uuid, 'efc6493b-a5c3-5b71-ac25-181b5fb94074'::uuid, 'Qui est Roderick Usher ?', 'mcq', '["Le dernier héritier d’une famille éteinte, ami du narrateur","Le médecin du village","Le père du narrateur","Un aubergiste"]'::jsonb, 0, 'Il est hypersensible et terrifié par les sensations.', 2),
    ('9e6f9c9e-629b-5e22-818f-89b4e61eaef6'::uuid, 'efc6493b-a5c3-5b71-ac25-181b5fb94074'::uuid, 'Que devient Madeline Usher ?', 'mcq', '["Elle est enterrée vivante et reparaît","Elle s’enfuit de la maison","Elle épouse le narrateur","Elle disparaît sans laisser de trace"]'::jsonb, 0, 'Elle entraîne son frère dans la mort.', 3),
    ('b0d55719-a43c-58fd-a950-378803d93a28'::uuid, 'efc6493b-a5c3-5b71-ac25-181b5fb94074'::uuid, 'Que se passe-t-il à la fin de la nouvelle ?', 'mcq', '["La maison se fend et sombre dans l’étang","Le narrateur hérite du domaine","La maison est vendue","Madeline survit seule"]'::jsonb, 0, 'La lignée et le bâtiment s’effondrent ensemble.', 4),
    ('cd9d6b21-bc1f-5d17-8055-225fdc8153a2'::uuid, 'efc6493b-a5c3-5b71-ac25-181b5fb94074'::uuid, 'Qu’est-ce qu’un modalisateur ?', 'mcq', '["Un mot qui exprime le doute, comme « il me sembla » ou « peut-être »","Un adjectif qui décrit un décor","Un verbe de mouvement","Un signe de ponctuation"]'::jsonb, 0, 'Il maintient l’hésitation propre au fantastique.', 5),
    ('42ffad63-cc5e-5d27-a05c-c233294319b2'::uuid, 'efc6493b-a5c3-5b71-ac25-181b5fb94074'::uuid, 'Quel type de narrateur Poe emploie-t-il ?', 'mcq', '["Un narrateur interne, témoin, dont on peut douter","Un narrateur omniscient","Un narrateur absent","Plusieurs narrateurs successifs"]'::jsonb, 0, 'Le doute sur sa fiabilité nourrit le fantastique.', 6),
    ('bf066a4a-980f-5781-b404-a3382a679c81'::uuid, 'efc6493b-a5c3-5b71-ac25-181b5fb94074'::uuid, 'Pourquoi le titre est-il double ?', 'mcq', '["« Maison » désigne à la fois le bâtiment et la lignée","La nouvelle comporte deux maisons","Le titre a été traduit deux fois","Usher possédait deux domaines"]'::jsonb, 0, 'L’anglais « house » porte les deux sens.', 7),
    ('8412fbf2-7228-506d-bcfa-d305dbf68343'::uuid, 'efc6493b-a5c3-5b71-ac25-181b5fb94074'::uuid, 'Dans le fantastique, le surnaturel est toujours expliqué à la fin.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'L’hésitation reste ouverte : c’est la définition même du genre.', 8),
    ('d276c0a2-2d6a-54a9-98d8-d70dc496cb69'::uuid, '029d706e-6b92-51f6-bb06-0fceda218555'::uuid, 'À quelles questions un article informatif doit-il répondre ?', 'mcq', '["Qui, quoi, quand, où, pourquoi","Comment, combien, pour qui","Qui, contre qui, pour quel prix","Quand et seulement quand"]'::jsonb, 0, 'La règle dite des cinq W.', 1),
    ('b7f239c6-a450-5505-b78c-e868ccd35240'::uuid, '029d706e-6b92-51f6-bb06-0fceda218555'::uuid, 'Qu’est-ce que le chapô d’un article ?', 'mcq', '["Le paragraphe d’introduction, souvent en gras","Le titre principal","La dernière phrase","La légende de la photo"]'::jsonb, 0, 'Il résume l’essentiel avant le corps de l’article.', 2),
    ('37e170bd-8d63-58d9-a4cd-45fddaaced7e'::uuid, '029d706e-6b92-51f6-bb06-0fceda218555'::uuid, 'Quel genre journalistique exprime une opinion ?', 'mcq', '["L’éditorial","La brève","Le reportage","L’interview"]'::jsonb, 0, 'La chronique et la critique aussi.', 3),
    ('8e3f8833-f744-51d5-89d7-4d473b6a9d61'::uuid, '029d706e-6b92-51f6-bb06-0fceda218555'::uuid, 'Que faut-il vérifier en premier devant une information ?', 'mcq', '["Sa source et sa date","Le nombre de partages","La qualité de l’image","La longueur du texte"]'::jsonb, 0, 'Une image ancienne remise en circulation change de sens.', 4),
    ('91092043-d533-52ab-aa56-0dc9247419df'::uuid, '029d706e-6b92-51f6-bb06-0fceda218555'::uuid, 'Qu’est-ce qu’un titre-appât (« putaclic ») ?', 'mcq', '["Un titre spectaculaire qui promet plus que l’article ne donne","Un titre trop long","Un titre sans verbe","Un titre en langue étrangère"]'::jsonb, 0, 'Il vise le clic, pas l’information.', 5),
    ('c908999d-4846-5e82-af35-06961aba1a12'::uuid, '029d706e-6b92-51f6-bb06-0fceda218555'::uuid, 'Qu’est-ce que la bulle de filtres ?', 'mcq', '["L’effet des algorithmes qui montrent surtout ce qui confirme nos idées","Un filtre appliqué aux photos de presse","Une technique de vérification","Un logiciel anti-spam"]'::jsonb, 0, 'Elle réduit la diversité des points de vue rencontrés.', 6),
    ('7314abc1-a208-56f5-bc5f-ef89fa009c04'::uuid, '029d706e-6b92-51f6-bb06-0fceda218555'::uuid, 'Quelle loi garantit la liberté de la presse en France ?', 'mcq', '["La loi de 1881","La loi de 1789","La loi de 1905","La loi de 1958"]'::jsonb, 0, 'Elle connaît des limites : diffamation, injure, incitation à la haine.', 7),
    ('2d6174d4-653a-51d4-9cc2-12984484ae51'::uuid, '029d706e-6b92-51f6-bb06-0fceda218555'::uuid, 'Une rumeur et une infox sont exactement la même chose.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'L’infox est fabriquée pour tromper ; la rumeur circule souvent de bonne foi.', 8),
    ('b4cd2082-1571-5e4e-a8da-9562ecaab285'::uuid, '4266b09c-f867-5d4a-b96a-a99c8993c624'::uuid, 'Quel est le but de la propagande ?', 'mcq', '["Faire adhérer à une opinion, pas informer","Vendre un produit commercial","Divertir le public","Enseigner une méthode"]'::jsonb, 0, 'Elle s’adresse à l’émotion plutôt qu’au raisonnement.', 1),
    ('52350164-0b1f-5401-9e1c-5a47332f4655'::uuid, '4266b09c-f867-5d4a-b96a-a99c8993c624'::uuid, 'Quel procédé consiste à réduire un problème complexe à une formule ?', 'mcq', '["La simplification","Le recoupement","La nuance","La citation"]'::jsonb, 0, 'Souvent associée à la répétition d’un slogan.', 2),
    ('30ebf2a4-5a11-5956-9dc0-aea9620616a3'::uuid, '4266b09c-f867-5d4a-b96a-a99c8993c624'::uuid, 'Qu’est-ce que la désignation d’un ennemi ?', 'mcq', '["La construction d’un « eux » responsable de tout, opposé à un « nous »","La déclaration de guerre officielle","La critique d’un adversaire politique argumentée","Le refus de nommer ses sources"]'::jsonb, 0, 'C’est l’un des ressorts les plus constants de la propagande.', 3),
    ('4478ddb7-9de7-586c-b483-5bce034a2ae0'::uuid, '4266b09c-f867-5d4a-b96a-a99c8993c624'::uuid, 'Qu’est-ce qu’un plan en contre-plongée dans une image de propagande ?', 'mcq', '["Un cadrage vu d’en bas, qui grandit le personnage","Un cadrage vu d’en haut, qui écrase le personnage","Un gros plan sur les mains","Un plan tourné de nuit"]'::jsonb, 0, 'Il sert le culte du chef.', 4),
    ('7881ea18-d3c2-572a-88d8-c2d4424c18f0'::uuid, '4266b09c-f867-5d4a-b96a-a99c8993c624'::uuid, 'Que faut-il identifier en premier dans un document de propagande ?', 'mcq', '["Son auteur et son commanditaire","Sa longueur","Le nombre de couleurs employées","Sa police de caractères"]'::jsonb, 0, 'Qui parle, et pour le compte de qui ?', 5),
    ('2de28630-687f-53e2-8b1e-b56918ed81c6'::uuid, '4266b09c-f867-5d4a-b96a-a99c8993c624'::uuid, 'Qu’est-ce qu’un message implicite ?', 'mcq', '["Ce que le document fait croire sans le dire","Le titre du document","La légende officielle","La signature de l’auteur"]'::jsonb, 0, 'Il se distingue du message explicite.', 6),
    ('1f46c670-4c89-5253-9f46-9232a414bbb6'::uuid, '4266b09c-f867-5d4a-b96a-a99c8993c624'::uuid, 'Comment une image peut-elle tromper sans être truquée ?', 'mcq', '["Par son cadrage, sa légende et son contexte de publication","Par sa taille","Par sa date de prise de vue seule","Par son format de fichier"]'::jsonb, 0, 'On lui fait dire ce qu’elle ne montre pas.', 7),
    ('86102f6d-c8f1-5581-8ed7-4541f49bbade'::uuid, '4266b09c-f867-5d4a-b96a-a99c8993c624'::uuid, 'La propagande et la publicité poursuivent le même objet.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La publicité vend un produit ; la propagande vise l’adhésion politique ou idéologique.', 8),
    ('0c515e7e-e15c-5c45-866d-64bb692246d9'::uuid, 'dd384a65-6e2e-5292-aefa-087e465b7138'::uuid, 'Quel roman de Balzac décrit le monde du journalisme parisien ?', 'mcq', '["Illusions perdues","Le Père Goriot","Bel-Ami","L’Assommoir"]'::jsonb, 0, 'Lucien de Rubempré y réussit puis s’y perd.', 1),
    ('b411d456-e5fd-510a-b1dd-23158c91b479'::uuid, 'dd384a65-6e2e-5292-aefa-087e465b7138'::uuid, 'Qui est le héros de Bel-Ami ?', 'mcq', '["Georges Duroy","Lucien de Rubempré","Roderick Usher","Rodrigue"]'::jsonb, 0, 'Il gravit les échelons d’un journal par les femmes et l’intrigue.', 2),
    ('2a866d96-c5d2-5400-8d1e-8bb0927a5935'::uuid, 'dd384a65-6e2e-5292-aefa-087e465b7138'::uuid, 'Que dénoncent Balzac et Maupassant à propos de la presse ?', 'mcq', '["Un système qui produit le mensonge, au-delà des individus","L’incompétence technique des imprimeurs","Le prix trop élevé des journaux","Le manque de lecteurs"]'::jsonb, 0, 'L’article s’y vend, la critique dépend de qui paie.', 3),
    ('b4021496-206a-5c45-9912-7a28184c692d'::uuid, 'dd384a65-6e2e-5292-aefa-087e465b7138'::uuid, 'Quel journaliste a défini le métier comme « porter la plume dans la plaie » ?', 'mcq', '["Albert Londres","Émile Zola","Guy de Maupassant","Honoré de Balzac"]'::jsonb, 0, 'Il est l’inventeur du grand reportage.', 4),
    ('6314f74f-780c-5654-89aa-398ddd023366'::uuid, 'dd384a65-6e2e-5292-aefa-087e465b7138'::uuid, 'Quel film suit deux journalistes révélant le scandale du Watergate ?', 'mcq', '["Les Hommes du président","Spotlight","Citizen Kane","La Parure"]'::jsonb, 0, 'Leur enquête mène à la démission d’un président.', 5),
    ('d264c3f4-8a18-581f-aa54-f51c6fd650d1'::uuid, 'dd384a65-6e2e-5292-aefa-087e465b7138'::uuid, 'Que montre le film Spotlight ?', 'mcq', '["Une équipe menant une enquête au long cours avant publication","Un journaliste corrompu","La naissance d’un journal","Une rédaction de télévision en direct"]'::jsonb, 0, 'Des mois de vérification y précèdent la publication.', 6),
    ('d84cc74a-445b-58fb-a3ac-8468adc30aa9'::uuid, 'dd384a65-6e2e-5292-aefa-087e465b7138'::uuid, 'Qu’apporte la fiction par rapport à un article de presse ?', 'mcq', '["Elle montre comment le fait a été obtenu et ce qu’il a coûté","Elle donne des informations plus récentes","Elle garantit la véracité des faits","Elle remplace le travail des journalistes"]'::jsonb, 0, 'Elle rend visibles les conditions du métier.', 7),
    ('6b56471b-af21-5871-9dea-817d04939104'::uuid, 'dd384a65-6e2e-5292-aefa-087e465b7138'::uuid, 'Dans Bel-Ami, Georges Duroy réussit grâce à son talent d’écriture.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il réussit par les femmes et l’intrigue, sans talent particulier.', 8),
    ('005640b9-4536-5bda-8d39-377a3ff7948e'::uuid, 'c630a319-c461-579a-a74f-1ba4cf2338ad'::uuid, 'Pourquoi la ville devient-elle un sujet de roman au XIXe siècle ?', 'mcq', '["Parce que l’exode rural et l’industrialisation la transforment radicalement","Parce que les romanciers y habitent tous","Parce que la campagne n’intéresse plus personne","Parce que l’imprimerie s’y installe"]'::jsonb, 0, 'Les grands travaux d’Haussmann changent Paris en trente ans.', 1),
    ('28512568-be28-5e5e-8abb-e63a38c208a9'::uuid, 'c630a319-c461-579a-a74f-1ba4cf2338ad'::uuid, 'Quel personnage de Balzac lance « À nous deux maintenant ! » à Paris ?', 'mcq', '["Rastignac","Lucien de Rubempré","Georges Duroy","Jean Valjean"]'::jsonb, 0, 'Il le lance du haut du Père-Lachaise.', 2),
    ('1f2f83ef-6f31-5ffb-b95a-06aa602ffa73'::uuid, 'c630a319-c461-579a-a74f-1ba4cf2338ad'::uuid, 'Comment Zola traite-t-il la ville ?', 'mcq', '["Comme un milieu qui détermine le destin des personnages","Comme un décor neutre","Comme un lieu de villégiature","Comme un souvenir d’enfance"]'::jsonb, 0, 'L’Assommoir se joue dans quelques rues de la Goutte-d’Or.', 3),
    ('4880d1a6-dc99-548b-86d8-19418148187d'::uuid, 'c630a319-c461-579a-a74f-1ba4cf2338ad'::uuid, 'Dans quel roman Paris est-il un labyrinthe d’égouts et de barricades ?', 'mcq', '["Les Misérables","L’Assommoir","Bel-Ami","Illusions perdues"]'::jsonb, 0, 'Hugo y fait de la ville un dédale.', 4),
    ('66fe8f50-d67e-574b-942f-756d4f693b32'::uuid, 'c630a319-c461-579a-a74f-1ba4cf2338ad'::uuid, 'Qu’est-ce que la personnification appliquée à la ville ?', 'mcq', '["Lui prêter des attributs humains : elle gronde, dévore, respire","La comparer à une autre ville","La décrire en détail","La nommer par son quartier"]'::jsonb, 0, 'C’est ce qui en fait un personnage à part entière.', 5),
    ('0f1fac5b-c5dc-57ad-88e5-ccd8bb79e8a6'::uuid, 'c630a319-c461-579a-a74f-1ba4cf2338ad'::uuid, 'Qu’est-ce que la focalisation interne dans une description de ville ?', 'mcq', '["La ville vue par les yeux d’un personnage","Une description faite par le narrateur omniscient","Une description objective et chiffrée","Un plan de la ville"]'::jsonb, 0, 'Souvent au moment de son arrivée.', 6),
    ('dc59fb42-00c1-5103-acca-c800161dc118'::uuid, 'c630a319-c461-579a-a74f-1ba4cf2338ad'::uuid, 'Que révèle le choix de ce qu’on décrit dans une ville ?', 'mcq', '["L’intention du romancier, son jugement sur elle","La saison de l’année","Le budget du roman","La longueur du chapitre"]'::jsonb, 0, 'Montrer les vitrines ou les taudis n’est jamais neutre.', 7),
    ('0de9ef67-08be-5d84-89ef-23684f81931a'::uuid, 'c630a319-c461-579a-a74f-1ba4cf2338ad'::uuid, 'Dans le roman du XIXe siècle, la ville n’est qu’un décor sans influence.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle devient un acteur, et chez Zola elle détermine les destins.', 8),
    ('991bd030-8d55-5334-abc6-fc373140ccaa'::uuid, '075ce4d2-072d-5d6c-90e2-2cb9d643b3a3'::uuid, 'Quel recueil contient la section « Tableaux parisiens » ?', 'mcq', '["Les Fleurs du mal","Alcools","Les Contemplations","Illuminations"]'::jsonb, 0, 'Baudelaire y fait de Paris un sujet poétique.', 1),
    ('b0929aea-7070-5ff3-ad22-971b181b22c6'::uuid, '075ce4d2-072d-5d6c-90e2-2cb9d643b3a3'::uuid, 'Qu’est-ce qu’un flâneur chez Baudelaire ?', 'mcq', '["Un poète qui marche dans la ville et capte les instants","Un promeneur de campagne","Un journaliste enquêteur","Un habitant sans domicile"]'::jsonb, 0, 'Il observe la passante, la vieille femme, l’aveugle.', 2),
    ('b24da792-124b-5267-83a2-18bdd5d2f083'::uuid, '075ce4d2-072d-5d6c-90e2-2cb9d643b3a3'::uuid, 'Que signifie « Tu m’as donné ta boue et j’en ai fait de l’or » ?', 'mcq', '["Le poète transfigure la laideur de la ville en poésie","Le poète s’est enrichi grâce à la ville","La ville a été reconstruite en or","Le poète regrette la campagne"]'::jsonb, 0, 'C’est le programme de la poésie urbaine.', 3),
    ('b9cf8d7b-a501-528d-a98f-96d9a974a34c'::uuid, '075ce4d2-072d-5d6c-90e2-2cb9d643b3a3'::uuid, 'Quel poème d’Apollinaire ouvre Alcools sur un Paris moderne ?', 'mcq', '["« Zone »","« Le Pont Mirabeau »","« Demain, dès l’aube… »","« Le Cygne »"]'::jsonb, 0, 'Publié en 1913, sans ponctuation.', 4),
    ('3b68e7aa-0c03-54b7-a0a5-e78cdd46f561'::uuid, '075ce4d2-072d-5d6c-90e2-2cb9d643b3a3'::uuid, 'Qu’est-ce qu’un oxymore ?', 'mcq', '["L’association de deux mots de sens contraires, comme « soleil noir »","Une répétition de sons","Une comparaison développée","Une exagération"]'::jsonb, 0, 'Il permet de dire la beauté du laid.', 5),
    ('4d00b3a6-81be-5af0-9026-46daec914393'::uuid, '075ce4d2-072d-5d6c-90e2-2cb9d643b3a3'::uuid, 'Qu’est-ce qu’une synesthésie ?', 'mcq', '["Le mélange de sensations de natures différentes","La répétition d’un vers","Une rime intérieure","Un vers de douze syllabes"]'::jsonb, 0, 'Bruits, odeurs et couleurs y sont associés.', 6),
    ('67bd4d41-5756-504a-bb05-fd3b98c9b939'::uuid, '075ce4d2-072d-5d6c-90e2-2cb9d643b3a3'::uuid, 'Quelle forme poétique s’impose pour dire le désordre urbain ?', 'mcq', '["Le vers libre et le poème en prose","Le sonnet","L’alexandrin à rimes plates","La ballade"]'::jsonb, 0, 'Des formes assez souples pour épouser la ville moderne.', 7),
    ('3c014c7c-419c-542a-bd00-495d6816a87b'::uuid, '075ce4d2-072d-5d6c-90e2-2cb9d643b3a3'::uuid, 'La poésie de la ville cherche à embellir ce qu’elle décrit.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle transfigure : elle rend visible ce que personne ne regarde.', 8),
    ('c94661d6-c43f-5862-a28c-856b78c99f2b'::uuid, 'f9a12b39-2235-541e-9d4c-9282f050b100'::uuid, 'Quel récit de 1841 est considéré comme le premier roman policier ?', 'mcq', '["« Double assassinat dans la rue Morgue » de Poe","Le Mystère de la chambre jaune","Une étude en rouge","Arsène Lupin gentleman-cambrioleur"]'::jsonb, 0, 'Le chevalier Dupin y résout l’énigme par la déduction.', 1),
