    ('1fbd6e04-6f06-56a2-b9ea-83e282322e41'::uuid, 'f9a12b39-2235-541e-9d4c-9282f050b100'::uuid, 'Quel roman de Gaston Leroux est le modèle du crime en chambre close ?', 'mcq', '["Le Mystère de la chambre jaune","Bel-Ami","Les Misérables","La Parure"]'::jsonb, 0, 'Publié en 1907.', 3),
    ('ddc75d5c-c1a5-537f-945f-cf4cad6f7704'::uuid, 'f9a12b39-2235-541e-9d4c-9282f050b100'::uuid, 'Quel personnage de Maurice Leblanc inverse les rôles du policier et du voleur ?', 'mcq', '["Arsène Lupin","Maigret","Sherlock Holmes","Rouletabille"]'::jsonb, 0, 'Le gentleman-cambrioleur est le héros.', 4),
    ('f645f639-4b1a-5ecd-9d9f-a66fd878b476'::uuid, 'f9a12b39-2235-541e-9d4c-9282f050b100'::uuid, 'Sur quoi reposent les enquêtes du commissaire Maigret ?', 'mcq', '["Sur l’atmosphère d’un lieu plus que sur l’indice","Sur des analyses scientifiques","Sur des courses-poursuites","Sur des interrogatoires musclés"]'::jsonb, 0, 'Un café, un quartier, une pluie sur la Seine.', 5),
    ('6906fe3f-9f69-56f4-adba-e61b5507b79e'::uuid, 'f9a12b39-2235-541e-9d4c-9282f050b100'::uuid, 'Qu’est-ce qui caractérise le roman noir ?', 'mcq', '["Une société corrompue, un détective désabusé, une ville hostile","Une énigme résolue par la logique","Un suspense permanent sans enquête","Une intrigue historique"]'::jsonb, 0, 'Chandler et Manchette en sont des maîtres.', 6),
    ('91c60a88-4370-58a8-b642-14a8ee6c6d99'::uuid, 'f9a12b39-2235-541e-9d4c-9282f050b100'::uuid, 'Qu’apporte la grande ville au roman policier ?', 'mcq', '["L’anonymat, la variété sociale et une atmosphère","Un climat plus doux","Des personnages plus riches","Une intrigue plus courte"]'::jsonb, 0, 'Maigret n’existe pas hors de Paris.', 7),
    ('5c8d45a1-5a0a-5534-a3e4-73e0af8e926f'::uuid, 'f9a12b39-2235-541e-9d4c-9282f050b100'::uuid, 'Le roman policier existait bien avant les grandes villes modernes.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il naît avec elles, au XIXe siècle : il lui faut une foule et une police organisée.', 8),
    ('ba29c38a-8ff2-5786-8861-4514106b9748'::uuid, '97bcdad8-2a45-5017-819b-7270ddffbacd'::uuid, 'Quel photographe a documenté le vieux Paris avant sa disparition ?', 'mcq', '["Eugène Atget","Robert Doisneau","Willy Ronis","Henri Cartier-Bresson"]'::jsonb, 0, 'Rues vides, boutiques et cours, dans un travail d’archive.', 1),
    ('0f7b5fab-9007-5e7b-a16f-375802b5fbad'::uuid, '97bcdad8-2a45-5017-819b-7270ddffbacd'::uuid, 'Qu’est-ce que le cadrage en photographie ?', 'mcq', '["Le choix de ce que l’image garde et de ce qu’elle exclut","Le réglage de la lumière","Le format d’impression","Le choix de l’appareil"]'::jsonb, 0, 'Ce qui est hors champ compte autant que ce qui est montré.', 2),
    ('ad913064-a96d-532a-9d2d-7d2d7a228a5e'::uuid, '97bcdad8-2a45-5017-819b-7270ddffbacd'::uuid, 'Qu’est-ce qu’une contre-plongée ?', 'mcq', '["Une prise de vue d’en bas, qui grandit le sujet","Une prise de vue d’en haut","Une photo prise de nuit","Un cadrage très serré"]'::jsonb, 0, 'La plongée, à l’inverse, écrase le sujet.', 3),
    ('2b0ec515-fac2-5f85-b125-a983e0fde44d'::uuid, '97bcdad8-2a45-5017-819b-7270ddffbacd'::uuid, 'Quel film de 1927 met en scène une ville verticale et divisée ?', 'mcq', '["Metropolis","Blade Runner","La Haine","Les Hommes du président"]'::jsonb, 0, 'Fritz Lang y installe les ouvriers sous terre et les maîtres au sommet.', 4),
    ('36adeffd-8467-5740-8ae3-3574358f0f3f'::uuid, '97bcdad8-2a45-5017-819b-7270ddffbacd'::uuid, 'Qu’est-ce qu’un plan général au cinéma ?', 'mcq', '["Un plan large qui situe l’action dans son décor","Un gros plan sur un visage","Un plan filmé en mouvement","Un plan sans son"]'::jsonb, 0, 'Le gros plan sert, lui, l’émotion.', 5),
    ('5f49a0cf-55db-53c1-aa80-c246f4b8d184'::uuid, '97bcdad8-2a45-5017-819b-7270ddffbacd'::uuid, 'Comment appelle-t-on le texte du narrateur en bande dessinée ?', 'mcq', '["Le cartouche","La bulle","La case","La planche"]'::jsonb, 0, 'La bulle contient les paroles des personnages.', 6),
    ('302e85f0-4670-57a4-ad93-80c2b070a4fa'::uuid, '97bcdad8-2a45-5017-819b-7270ddffbacd'::uuid, 'Quelle série de bande dessinée invente des villes entières comme personnages ?', 'mcq', '["Les Cités obscures, de Schuiten et Peeters","Les Aventures de Tintin","Les Misérables en BD","Astérix"]'::jsonb, 0, 'La ville y est le sujet même du récit.', 7),
    ('f3736aac-32c5-5384-9b36-46f7e5caf79f'::uuid, '97bcdad8-2a45-5017-819b-7270ddffbacd'::uuid, 'En bande dessinée, tout ce qui se passe est montré dans les cases.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Entre deux cases, une ellipse laisse au lecteur le soin de combler.', 8)
  ) AS v(id, quiz_id, question, kind, options, correct_index, explanation, position)
-- Le quiz doit exister : si le NOT EXISTS ci-dessus a écarté un quiz (une
-- leçon en avait déjà un), ses questions ne partent pas dans le vide.
 WHERE EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.id = v.quiz_id)
ON CONFLICT (id) DO NOTHING;

-- 5. Sonde finale ----------------------------------------------------------
DO $$
DECLARE
  n_vides integer;
  n_chap  integer;
BEGIN
  SELECT count(*) INTO n_chap FROM public.chapters c
   JOIN public.subjects s ON s.id = c.subject_id
   WHERE s.slug IN ('francais');
  SELECT count(*) INTO n_vides FROM public.subjects s
   WHERE s.slug IN ('francais')
     AND NOT EXISTS (SELECT 1 FROM public.chapters c WHERE c.subject_id = s.id);
  IF n_vides > 0 THEN
    RAISE EXCEPTION 'Migration 300 incomplète : % matiere(s) encore sans chapitre', n_vides;
  END IF;
  RAISE NOTICE 'Migration 300 OK : % chapitres sur les matieres visees.', n_chap;
END $$;
